/* ─── FORM ─── */
var fd={s1:null,s2:[],s3:null};
function goTo(id){document.getElementById(id).scrollIntoView({behavior:'smooth'});}
function updDots(step){for(var i=1;i<=5;i++){var d=document.getElementById('d'+i);d.classList.toggle('done',i<step);d.classList.toggle('active',i===step);if(i>step)d.classList.remove('done','active');}}
function pick(el,step){el.closest('.form-opts').querySelectorAll('.form-opt').forEach(function(o){o.classList.remove('sel');});el.classList.add('sel');fd['s'+step]=el.querySelector('strong').textContent;var nb=document.getElementById('n'+step);if(nb)nb.disabled=false;if(step===3)ai3(fd.s3);}
function tog(el){el.classList.toggle('sel');fd.s2=Array.from(document.querySelectorAll('#t2 .ftag.sel')).map(function(t){return t.textContent.trim();});}
function ns(from){document.getElementById('s'+from).classList.remove('active');var nx=from+1;var nxEl=document.getElementById('s'+nx);if(nxEl)nxEl.classList.add('active');updDots(nx);if(nx===5)aiF();reobserve();}
function ai3(b){var m={'At\u00e9 R$ 10.000':'Com esse or\u00e7amento, monto um MVP s\u00f3lido focado no seu principal objetivo.','R$ 10.000 \u2013 R$ 30.000':'Essa faixa \u00e9 ideal para uma solu\u00e7\u00e3o completa. Onde a maioria dos clientes tem os melhores resultados.','Acima de R$ 30.000':'Com esse investimento, constru\u00edmos um sistema robusto que escala com o neg\u00f3cio.'};var box=document.getElementById('ab3'),txt=document.getElementById('at3');box.classList.add('show');setTimeout(function(){txt.innerHTML=m[b]||'Entendido! Vou preparar uma proposta alinhada.';},1200);}
function aiF(){var goals=fd.s2.length?fd.s2.slice(0,3).join(', '):'suas necessidades';setTimeout(function(){document.getElementById('atf').innerHTML='Com base no que voc\u00ea compartilhou \u2014 <strong>'+(fd.s1||'seu contexto')+'</strong>, focando em '+goals+' \u2014 j\u00e1 consigo visualizar um tech-stack enxuto. Em breve voc\u00ea recebe a proposta!';},1500);}
async function sub(){
  var nm=document.getElementById('nm').value.trim();
  var em=document.getElementById('em').value.trim();
  var wh=(document.getElementById('wh')||{}).value||'';
  if(!nm||!em){alert('Preencha pelo menos seu nome e e-mail!');return;}
  var btn=document.getElementById('subBtn');
  btn.disabled=true;btn.textContent='Enviando...';
  // Collect form answers from selections
  var ctx = document.querySelector('.form-step#s1 .form-opt.sel .form-opt-txt strong');
  var obj = Array.from(document.querySelectorAll('.form-step#s2 .ftag.on')).map(function(t){return t.textContent.trim();}).join(', ');
  var inv = document.querySelector('.form-step#s3 .form-opt.sel .form-opt-txt strong');
  var prz = document.querySelector('.form-step#s4 .form-opt.sel .form-opt-txt strong');
  var aiTxt = (document.getElementById('atf')||{}).textContent||'';
  try {
    await fetch('https://sdeowbqmwkwseyktyemn.supabase.co/functions/v1/send-lead-email',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({
        nome:nm, email:em, whatsapp:wh,
        contexto: ctx ? ctx.textContent : '',
        objetivos: obj,
        investimento: inv ? inv.textContent : '',
        prazo: prz ? prz.textContent : '',
        aiAnalysis: aiTxt
      })
    });
  } catch(e){ console.warn('Email send failed:',e); }
  document.querySelectorAll('.form-step').forEach(function(s){s.classList.remove('active');});
  document.getElementById('fdone').classList.add('show');
  document.querySelector('.form-prog').style.display='none';
}

