/* ── PRICING COMPARISON ANIMATION ── */
(function(){
  var obs=new IntersectionObserver(function(es){
    es.forEach(function(e){
      if(!e.isIntersecting) return;
      e.target.querySelectorAll('.cmp-bar-fill').forEach(function(b){
        var w=b.style.width;
        b.style.width='0';
        requestAnimationFrame(function(){
          setTimeout(function(){
            b.style.transition='width 1.3s cubic-bezier(.34,1.1,.64,1)';
            b.style.width=w;
          },80);
        });
      });
      obs.unobserve(e.target);
    });
  },{threshold:.25});
  var wrap=document.querySelector('.cmp-wrap');
  if(wrap) obs.observe(wrap);
})();

/* ─── CURSOR ─── */
(function(){
  if('ontouchstart' in window || navigator.maxTouchPoints > 0) return;
  var cur=document.getElementById('cur'),curR=document.getElementById('curR');
  if(!cur||!curR) return;
  var mx=0,my=0,rx=0,ry=0;
  document.addEventListener('mousemove',function(e){mx=e.clientX;my=e.clientY;});
  (function tick(){
    rx+=(mx-rx)*.11; ry+=(my-ry)*.11;
    cur.style.left=mx-5+'px'; cur.style.top=my-5+'px';
    curR.style.left=rx-19+'px'; curR.style.top=ry-19+'px';
    requestAnimationFrame(tick);
  })();
  document.querySelectorAll('button,a,.form-opt,.ftag,.plat-chip,.mod-card,.uc,.sol-item,.sol-tab').forEach(function(el){
    el.addEventListener('mouseenter',function(){cur.style.transform='scale(2.2)';curR.style.transform='scale(1.6)';cur.style.background='var(--red)';});
    el.addEventListener('mouseleave',function(){cur.style.transform='scale(1)';curR.style.transform='scale(1)';cur.style.background='var(--blue)';});
  });
})();














