/* ── VISUAL HELPERS (shared with original hub) ── */
function hkpi(label,val,trend,color){
  return '<div class="hd-kpi"><div class="hd-kpi-v" style="color:'+(color||'var(--white)')+'">'+val+'</div><div class="hd-kpi-l">'+label+'</div>'+(trend?'<div class="hd-kpi-t">'+trend+'</div>':'')+'</div>';
}
function hcard(content,extra){
  return '<div class="hd-card'+(extra?' '+extra:'')+'">'+(content)+'</div>';
}
function hrow(label,val,bar,color){
  return '<div class="hd-row"><span class="hd-row-lbl">'+label+'</span><div class="hd-row-bar-wrap"><div class="hd-row-bar" style="width:'+bar+'%;background:'+color+'"></div></div><span class="hd-row-val">'+val+'</span></div>';
}
function hbars(data,colors,h){
  var max=Math.max.apply(null,data);
  return data.map(function(v,i){
    var pct=Math.round(v/max*100);
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center"><div style="flex:1;display:flex;align-items:flex-end;width:100%"><div class="hd-bar" style="width:100%;height:100%;background:'+colors[i%colors.length]+';border-radius:3px 3px 0 0;transform:scaleY('+pct/100+')"></div></div></div>';
  }).join('');
}
function sparkline(pts,color){
  var max=Math.max.apply(null,pts),min=Math.min.apply(null,pts);
  var w=200,h=50;
  var coords=pts.map(function(v,i){
    return (i/(pts.length-1)*w)+','+(h-(v-min)/(max-min||1)*h);
  });
  return '<svg viewBox="0 0 200 50" style="width:100%;height:40px"><polyline points="'+coords.join(' ')+'" fill="none" stroke="'+color+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}
function donut(pct,color,size){
  size=size||64; var r=size*.38,circ=2*Math.PI*r,dash=circ*pct/100;
  return '<svg viewBox="0 0 '+size+' '+size+'" style="width:'+size+'px;height:'+size+'px;transform:rotate(-90deg)">'+
    '<circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="rgba(255,255,255,.07)" stroke-width="'+size*.1+'"/>'+
    '<circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="'+color+'" stroke-width="'+size*.1+'" stroke-dasharray="'+dash+' '+(circ-dash)+'" stroke-linecap="round" class="hd-donut"/>'+
    '</svg>';
}
function stitle(t,period){ return '<div class="hd-section-title">'+t+(period?' <span class="hd-period">'+period+'</span>':'')+'</div>'; }
function animateMain(el){
  setTimeout(function(){
    el.querySelectorAll('.hd-bar').forEach(function(b,i){var t=b.style.transform||'scaleY(1)';b.style.transition='none';b.style.transform='scaleY(0)';requestAnimationFrame(function(){setTimeout(function(){b.style.transition='transform .8s cubic-bezier(.34,1.2,.64,1)';b.style.transform=t;},i*35);});});
    el.querySelectorAll('.hd-row-bar').forEach(function(b){var w=b.style.width;b.style.width='0';b.style.transition='width 1s ease';setTimeout(function(){b.style.width=w;},100);});
    el.querySelectorAll('.hd-donut').forEach(function(d){var da=d.getAttribute('stroke-dasharray').split(' ')[0];var tot=parseFloat(d.getAttribute('stroke-dasharray').split(' ')[1]);d.setAttribute('stroke-dasharray','0 '+tot);d.style.transition='stroke-dasharray 1.1s ease';setTimeout(function(){d.setAttribute('stroke-dasharray',da+' '+(tot-da));},80);});
  },60);
}

